import pandas as pd
from sklearn.metrics import accuracy_score, confusion_matrix, f1_score, precision_score, recall_score

from src.config import LABEL_NAMES

# Evaluation of the final models on a held-out set
# Class 1 (generated by GPT-4) is the positive class for precision, recall and F1.

def predict(models, data):
    # One row per review: id, true label, sentiment and the prediction of every model.

    predictions = data[["id", "label", "sentiment"]].rename(columns={"label": "y_true"}).reset_index(drop=True)
    for name, model in models.items():
        predictions[f"pred_{name}"] = model.predict(data["clean_text"])
    return predictions


def metrics(y_true, y_pred):
    return {
        "accuracy": accuracy_score(y_true, y_pred),
        "precision": precision_score(y_true, y_pred),
        "recall": recall_score(y_true, y_pred),
        "f1": f1_score(y_true, y_pred),
    }


def metrics_table(predictions, models):
    table = pd.DataFrame(
        {name: metrics(predictions["y_true"], predictions[f"pred_{name}"]) for name in models}
    ).T
    return table.round(4).rename_axis("model")


def confusion_table(predictions, name):
    # Rows: predicted class, columns: true class (as table(pred, true) in the course)
    labels = list(LABEL_NAMES)
    matrix = confusion_matrix(predictions["y_true"], predictions[f"pred_{name}"], labels=labels).T
    names = [LABEL_NAMES[label] for label in labels]
    return pd.DataFrame(
        matrix,
        index=pd.Index([f"predicted {n}" for n in names], name=name),
        columns=[f"true {n}" for n in names],
    )


def accuracy_by_sentiment(predictions, models):
    # Accuracy on positive and negative reviews separately
    rows = {}
    for sentiment, group in predictions.groupby("sentiment"):
        rows[sentiment] = {
            name: accuracy_score(group["y_true"], group[f"pred_{name}"]) for name in models
        } | {"reviews": len(group)}
    return pd.DataFrame(rows).T.round(4).rename_axis("sentiment")


def evaluate(models, data):
    # Predictions and result tables of all models on `data`
    predictions = predict(models, data)
    tables = {"Performance (positive class: ai)": metrics_table(predictions, models)}
    for name in models:
        tables[f"Confusion matrix: {name}"] = confusion_table(predictions, name)
    tables["Accuracy by sentiment"] = accuracy_by_sentiment(predictions, models)
    return predictions, tables


def save_predictions(predictions, path):
    path.parent.mkdir(parents=True, exist_ok=True)
    predictions.to_csv(path, index=False)
